import * as TrueForgeTypes from "../../src/api/index";
import { TrueForge } from "../../src/Client";
import { mockServerPool } from "../mock-server/MockServerPool";

describe("AuthClient", () => {
    test("me (1)", async () => {
        const server = mockServerPool.createServer();
        const client = new TrueForge({ maxRetries: 0, token: "test", baseUrl: server.baseUrl });

        const rawResponseBody = {
            is_admin: true,
            subject: { display_name: "display_name", id: "id", type: "user" },
            tenant_id: "tenant_id",
        };

        server.mockEndpoint().get("/api/v1/auth/me").respondWith().statusCode(200).jsonBody(rawResponseBody).build();

        const response = await client.auth.me();
        expect(response).toEqual({
            isAdmin: true,
            subject: {
                displayName: "display_name",
                id: "id",
                type: "user",
            },
            tenantId: "tenant_id",
        });
    });

    test("me (2)", async () => {
        const server = mockServerPool.createServer();
        const client = new TrueForge({ maxRetries: 0, token: "test", baseUrl: server.baseUrl });

        const rawResponseBody = { error: { message: "message" } };

        server.mockEndpoint().get("/api/v1/auth/me").respondWith().statusCode(401).jsonBody(rawResponseBody).build();

        await expect(async () => {
            return await client.auth.me();
        }).rejects.toThrow(TrueForgeTypes.UnauthorizedError);
    });
});
